using Rhino;
namespace RhinoContextAssist;
internal sealed class ContextAssistSettings {
 readonly PersistentSettings store; public bool Enabled{get;set;} public int PrimaryCount{get;set;} public PopupPositionMode PositionMode{get;set;} public bool AutomaticPrioritization{get;set;} public Dictionary<SelectionKind,List<ActionPreference>> Preferences{get;}=new(); public Dictionary<string,UsageEntry> Usage{get;}=new();
 public ContextAssistSettings(PersistentSettings s){store=s;Load();}
 void Load(){Enabled=store.GetBool("Enabled",true);PrimaryCount=Math.Clamp(store.GetInteger("PrimaryCount",3),1,5);PositionMode=store.GetEnumValue("PositionMode",PopupPositionMode.Mouse);AutomaticPrioritization=store.GetBool("AutomaticPrioritization",true);foreach(var k in ActionCatalog.ConfigurableKinds){var d=ActionCatalog.Defaults(k);var text=store.GetString($"Actions.{k}","");var known=d.ToDictionary(x=>x.Id);var list=new List<ActionPreference>();foreach(var row in text.Split(';',StringSplitOptions.RemoveEmptyEntries)){var p=row.Split('|');if(p.Length>=3&&known.ContainsKey(p[0]))list.Add(new(p[0],p[1]=="1",p[2]=="1"));}foreach(var a in d)if(list.All(x=>x.Id!=a.Id))list.Add(new(a.Id,true,false));Preferences[k]=list;}foreach(var row in store.GetString("Usage","").Split(';',StringSplitOptions.RemoveEmptyEntries)){var p=row.Split('|');if(p.Length==3&&long.TryParse(p[1],out var c)&&long.TryParse(p[2],out var t))Usage[p[0]]=new(p[0],c,new DateTime(t,DateTimeKind.Utc));}}
 public void Save(){store.SetBool("Enabled",Enabled);store.SetInteger("PrimaryCount",PrimaryCount);store.SetEnumValue("PositionMode",PositionMode);store.SetBool("AutomaticPrioritization",AutomaticPrioritization);foreach(var p in Preferences)store.SetString($"Actions.{p.Key}",string.Join(";",p.Value.Select(x=>$"{x.Id}|{(x.Enabled?1:0)}|{(x.Favorite?1:0)}")));store.SetString("Usage",string.Join(";",Usage.Values.Select(x=>$"{x.ActionId}|{x.Count}|{x.LastUsedUtc.Ticks}")));}
 public IReadOnlyList<ContextAction> Resolve(SelectionKind k){var cat=ActionCatalog.Defaults(k).ToDictionary(x=>x.Id);if(!Preferences.TryGetValue(k,out var p))return cat.Values.ToList();var q=p.Select((x,i)=>new{P=x,I=i}).Where(x=>x.P.Enabled&&cat.ContainsKey(x.P.Id));q=AutomaticPrioritization?q.OrderByDescending(x=>x.P.Favorite).ThenByDescending(x=>Usage.TryGetValue(x.P.Id,out var u)?u.Count:0).ThenBy(x=>x.I):q.OrderByDescending(x=>x.P.Favorite).ThenBy(x=>x.I);return q.Select(x=>cat[x.P.Id]).ToList();}
 public bool IsFavorite(SelectionKind k,string id)=>Preferences.TryGetValue(k,out var p)&&p.Any(x=>x.Id==id&&x.Favorite); public long UsageCount(string id)=>Usage.TryGetValue(id,out var u)?u.Count:0; public void RecordUsage(string id){var n=DateTime.UtcNow;Usage[id]=Usage.TryGetValue(id,out var u)?u with{Count=u.Count+1,LastUsedUtc=n}:new(id,1,n);Save();} public void ResetUsage(){Usage.Clear();Save();}
}
